// Язык: русский — ОСНОВНОЙ. Здесь ВСЕ строки игры: и надписи index.html, и весь текст из кода и данных (js/).
// Если в файле другого языка строки нет, игра показывает её отсюда (tr() в js/tr.js), поэтому новые строки пишутся ТОЛЬКО сюда.
//
// ===== КАК ПЕРЕВОДИТЬ (например, на английский — locales/en.js) =====
// 1. Скопировать строку отсюда в locales/en.js (внутрь LOCALES.en = { ... }) и заменить ТОЛЬКО значение справа от двоеточия.
//    "ui.Закрыть": "Закрыть",   →   "ui.Закрыть": "Close",
// 2. КЛЮЧ (слева, «ui.…») НЕ МЕНЯТЬ НИКОГДА — ни буквы, ни пробела, ни кавычки «ёлочки». По нему код находит строку;
//    изменённый ключ = перевод молча не работает (покажется русский).
// 3. Кавычки и запятые: значение в двойных кавычках "…", в конце строки запятая. Двойная кавычка внутри текста — \" ;
//    обратный слеш — \\ ; перенос строки — \n (оставить как есть). Апостроф ' можно писать свободно: It's.
// 4. {name}, {zone}, {enemy}, {n}, {times}, {gem}, {loot}, {skill}, {skillText}, {faction}, {level} — подстановки.
//    Не переводить и не менять внутри скобок; можно переставить в другое место фразы: "Kill {n} in {zone}".
// 5. Куски фраз. Многие строки — обрывки, между которыми код вставляет число или имя:
//    "ui.Отказаться от задания «" + название + "ui.»? Прогресс пропадёт."
//    Пробелы и знаки в начале и конце значения сохранять (" Заказчик обидится…" начинается с пробела — и перевод тоже).
//    Кавычки «» можно заменить на английские “ ” — но парно в обоих кусках.
// 6. HTML внутри строк (<b>, <br>, <div class=\"…\">, <span …>) — теги и атрибуты не трогать, переводить только текст между ними.
// 7. Множественное число: слова вида 'победа' / 'победы' / 'побед' — три формы для 1 / 2–4 / 5+ (plural в js/plural.js).
//    По-английски: первая форма — единственное число, вторая и третья — обе множественное: "win", "wins", "wins".
// 8. Длина: экран 820×360, кнопки узкие. Перевод не длиннее русского, по возможности короче; названия кнопок — 1–2 слова.
// 9. Стиль: юмор с сарказмом, постапокалиптический СССР (ориентиры — WoW, Fallout, Аллоды Онлайн). Имена (Семёныч,
//    Повесткин, Нина Петровна) — транслитом или говорящим аналогом, но одинаково во всех строках. Изолента — tape.
// 10. Строки, которых нет в en.js, игра покажет по-русски — переводить можно по частям, ничего не сломается.
//    Удалять строки из en.js не нужно, если они больше не используются — просто не будут показываться.
// 11. После правки: проверить, что файл открывается без ошибок (консоль браузера F12) — пропущенная запятая или кавычка
//     ломает ВЕСЬ язык. Предметы, уже созданные на русском, останутся русскими (они сохраняются готовым текстом).
//
// Чтобы добавить другой язык: создать locales/<код>.js с LOCALES.<код> = { … }, подключить в index.html, добавить в LANGUAGES (js/languages.js).
