  "ui.Задания бывают четырёх видов. Прогресс идёт в боях, сдавать — на доске.": "Задания бывают четырёх видов. Прогресс идёт в боях, сдавать — на доске.",
  "ui.Виды: победить врагов в локации, победить конкретного врага, одолеть элиту, собрать фишки (считаются и при поражении), одержать победы.": "Виды: победить врагов в локации, победить конкретного врага, одолеть элиту, собрать фишки (считаются и при поражении), одержать победы.",
  "ui.Награда — опыт, изолента, иногда магическая вещь; за элиту — всегда редкая.": "Награда — опыт, изолента, иногда магическая вещь; за элиту — всегда редкая.",
