  "ui.Уровень вещи — уровень врага; надеть можно с уровня на ": "Уровень вещи — уровень врага; надеть можно с уровня на ",
  "ui. ниже. Вещи падают в инвентарь (место дают надетые сумки), что не влезло — остаётся в пустошах.": " ниже. Вещи падают в инвентарь (место дают надетые сумки), что не влезло — остаётся в пустошах.",
  "ui.Надеть, снять или выбросить — касанием по вещи на экране «Персонаж». В бою снаряжение не меняется.": "Надеть, снять или выбросить — касанием по вещи на экране «Персонаж». В бою снаряжение не меняется.",
