  "ui.С побеждённых врагов падает 1–3 единицы (с элиты — вдвое больше). Хранятся в лагере, пригодятся для построек и крафта.": "С побеждённых врагов падает 1–3 единицы (с элиты — вдвое больше). Хранятся в лагере, пригодятся для построек и крафта.",
