  "ui.Оформлять можно только рядом с уже оформленной (от «Заявления о признании»). «Аннулировать всё» возвращает очки.": "Оформлять можно только рядом с уже оформленной (от «Заявления о признании»). «Аннулировать всё» возвращает очки.",
