  "ui.За врага своего уровня — 45 + 5 × уровень; за более сильного — больше, за слабого — меньше. Элита — ×2.": "За врага своего уровня — 45 + 5 × уровень; за более сильного — больше, за слабого — меньше. Элита — ×2.",
