  "ui.Сумка полна: добыча упадёт на землю.": "Сумка полна: добыча упадёт на землю.",
  "ui.Сумка набита под завязку! Всё, что выпадет, упадёт на землю — и местные разворуют это быстрее, чем вы скажете «моё». Разгрузитесь у Семёныча.": "Сумка набита под завязку! Всё, что выпадет, упадёт на землю — и местные разворуют это быстрее, чем вы скажете «моё». Разгрузитесь у Семёныча.",
