  "ui.Радиационный фон": "Радиационный фон",
  "ui.Каждые 5 ходов −5 % к эффективности всех фишек (до −30 %).": "Каждые 5 ходов −5 % к эффективности всех фишек (до −30 %).",
  "ui.Чем дольше ты здесь, тем слабее становишься.": "Чем дольше ты здесь, тем слабее становишься.",
  "ui.Разведчик‑Перехватчик Эхо": "Разведчик‑Перехватчик Эхо",
  "ui.Блокирует уникальные способности на 3 хода.": "Блокирует уникальные способности на 3 хода.",
  "ui.Перехватывает не только сигналы, но и возможности.": "Перехватывает не только сигналы, но и возможности.",
  "ui.Проводник‑Предатель Троп": "Проводник‑Предатель Троп",
  "ui.Ложный коридор": "Ложный коридор",
  "ui.При попытке перехода −20 % ресурсов и дебафф «потеря ориентации».": "При попытке перехода −20 % ресурсов и дебафф «потеря ориентации».",
  "ui.Показывает только те пути, что ведут в ловушку.": "Показывает только те пути, что ведут в ловушку.",
